body.onloadscript:

    targetId = Sepoa.request.UPLOAD_ID;
    house_code = Sepoa.request.HOUSE_CODE;
    house_name = Sepoa.request.HOUSE_NAME;
    company_code = Sepoa.params.COMPANY_CODE;
    formObj.hideItem('searchImg');
    formObj.setValue('HOUSE_NAME', house_name);
    formObj.setValue('HOUSE_CODE', house_code);
    formObj.setValue('COMPANY_CODE', company_code);
    colIdxCompany = gridObj.getColIndexById('COMPANY_CODE');
	colIdxDept = gridObj.getColIndexById('DEPT_CODE');
	colIdxDeptName = gridObj.getColIndexById('DEPT_NAME');
	colIdxPos = gridObj.getColIndexById('POSITION_CODE');
	colIdxPosName = gridObj.getColIndexById('POSITION_NAME');

userscript.function:

    if (gridObj.getRowsNum() == 0) {
		gridObj.loadExcel({});
	} else {
    	Confirm(Sepoa.cache.text.get('DF_001.doUpload'), function(result) {
        	if (result) {
            	gridObj.loadExcel({});
        	}
    	});
    }


        	dataOutput.setValue('HOUSE_CODE', formObj.getValue('HOUSE_CODE'));
        	var company_codes = [];
        	var depts = [];
        	var positions = [];
            for (var i = 0; i < gridObj.getRowsNum(); i++) {
                gridObj.cells2(i, gridObj.getColIndexById('ROW_NUM')).setValue(gridObj.getRowId(i));
                company_codes.push(gridObj.cells2(i, colIdxCompany).getValue());
                depts.push(gridObj.cells2(i, colIdxDept).getValue());
                positions.push(gridObj.cells2(i, colIdxPos).getValue());
            }
            dataOutput.setValue('COMPANY_CODES', company_codes);
            dataOutput.setValue('DEPTS', depts);
            dataOutput.setValue('POSITIONS', positions);
            doServiceAjax('sepoa.svc.info.SepoaInfoUploadService', 'CONNECTION', 'searchUserList', null, function(so){
	        	if (so.status == 1){
	        		var gridData = JSON.parse(so.param.params);
	        		for (var i = 0; i < gridObj.getRowsNum(); i++) {
	        			if (Sepoa.info.LANGUAGE == 'KO') {
	        				gridObj.cells2(i, colIdxDeptName).setValue(gridData[i].DEPT_NAME_LOC);
		                	gridObj.cells2(i, colIdxPosName).setValue(gridData[i].POSITION_NAME_LOC);
	        			} else if (Sepoa.info.LANGUAGE == 'JA') {
	        				gridObj.cells2(i, colIdxDeptName).setValue(gridData[i].DEPT_NAME_JP);
		                	gridObj.cells2(i, colIdxPosName).setValue(gridData[i].POSITION_NAME_JP);
	        			} else if (Sepoa.info.LANGUAGE == 'ZH') {
	        				gridObj.cells2(i, colIdxDeptName).setValue(gridData[i].DEPT_NAME_CN);
		                	gridObj.cells2(i, colIdxPosName).setValue(gridData[i].POSITION_NAME_CN);
	        			} else {
	        				gridObj.cells2(i, colIdxDeptName).setValue(gridData[i].DEPT_NAME_ENG);
		                	gridObj.cells2(i, colIdxPosName).setValue(gridData[i].POSITION_NAME_ENG);
	        			}
		            }
	        	} else {
	        		Alert(so.message);
	        	}
	        });

            for (var i = 0; i < gridObj.getRowsNum(); i++) {
                gridObj.cells2(i, gridObj.getColIndexById('ROW_NUM')).setValue(gridObj.getRowId(i));
                if (gridObj.cells2(i, gridObj.getColIndexById('LANGUAGE')).getValue() == '') {
                	gridObj.cells2(i, gridObj.getColIndexById('LANGUAGE')).setValue(Sepoa.config.get('sepoa.user.default.language'));
                }
                if (gridObj.cells2(i, gridObj.getColIndexById('TIME_ZONE')).getValue() == '') {
                	gridObj.cells2(i, gridObj.getColIndexById('TIME_ZONE')).setValue(Sepoa.config.get('sepoa.user.default.time_zone'));
                }
                if (gridObj.cells2(i, gridObj.getColIndexById('COUNTRY')).getValue() == '') {
                	gridObj.cells2(i, gridObj.getColIndexById('COUNTRY')).setValue(Sepoa.config.get('sepoa.user.default.country'));
                }
                if (gridObj.cells2(i, gridObj.getColIndexById('MENU_PROFILE_CODE')).getValue() == '') {
                	gridObj.cells2(i, gridObj.getColIndexById('MENU_PROFILE_CODE')).setValue(Sepoa.config.get('sepoa.default.porfile.code'));
                }
                if (gridObj.cells2(i, gridObj.getColIndexById('DATE_FORMAT')).getValue() == '') {
                	gridObj.cells2(i, gridObj.getColIndexById('DATE_FORMAT')).setValue(Sepoa.config.get('sepoa.user.default.date_format'));
                }
            }


if (gridObj.getRowsNum() < 1) {
    Alert(Sepoa.cache.text.get('MESSAGE.0004'));
    return;
}
gridObj.allRowsChecked('SELECTED', true);

var selectedRow = gridObj.getGridChangedRows("SELECTED");
if(!gridObj.validate()){
    Alert(Sepoa.cache.text.get('MESSAGE.0002'));
    return;
}

Confirm(Sepoa.cache.text.get('MESSAGE.1018'),function(result){
    if(result){
        gridObj.editStop();
        dataOutput.setValue('TARGET_HOUSE', formObj.getValue('HOUSE_CODE'));
        dataOutput.setValue('TARGET_COMPANY', formObj.getValue('COMPANY_CODE'));
        var params = [];
        params.push('mode=doSave');
        params.push('PROCESS_ID=sepoa.svc.info.SepoaInfoUploadService');
        params.push('METHOD=doUserSave');

        gridObj.postTransaction(window.CONTEXT_NAME+'/SepoaGrid.sux', params, 'SELECTED');
    }
});


var status = obj.status;
var message = obj.message;
var gridData = JSON.parse(obj.params);

for (var i = 0; i < gridData.length; i++) {
    gridObj.cells(gridData[i].ROW_NUM, gridObj.getColIndexById('STATUS')).setValue(gridData[i].STATUS);
    gridObj.cells(gridData[i].ROW_NUM, gridObj.getColIndexById('ERR_MSG')).setValue(gridData[i].ERR_MSG);
}
Alert(Sepoa.cache.text.get('DF_001.MSG_001'));


var selectedRow = gridObj.getGridChangedRows("SELECTED");
if (selectedRow.length < 1) {
    Alert(Sepoa.cache.text.get('MESSAGE.1004'));
    return;
}
Confirm(Sepoa.cache.text.get('DF_001.doDelete'),function(result){
    if(result) {
        for (var i = 0; i < selectedRow.length; i++)
            gridObj.deleteRow(selectedRow[i]);
    }
});


targetId = id;
var fileId = 'USER_MASTER_Template.xlsx'
sepoaExcelProcessor('down','sepoa.svc.info.SepoaInfoUploadService', 'doUserExcelDownload', null, fileId);


        	if (stage==2) {
	        	if (cInd==colIdxCompany || cInd==colIdxDept) {
	        		if (gridObj.cells(rId, colIdxDept).getValue()=='') {
	        			return false;
	        		}
	        		dataOutput.setValue('HOUSE_CODE', formObj.getValue('HOUSE_CODE'));
	        		dataOutput.setValue('COMPANY_CODE', gridObj.cells(rId, colIdxCompany).getValue());
	        		dataOutput.setValue('DEPT_CODE', gridObj.cells(rId, colIdxDept).getValue());
	        		doServiceAjax('sepoa.svc.info.SepoaInfoUploadService', 'CONNECTION', 'searchDept', null, function(so){
	        			if (so.status == 1){
	        				var sf = new SepoaFormater(so.result[0]);
	        				if (Sepoa.info.LANGUAGE == 'KO') {
		        				gridObj.cells(rId, colIdxDeptName).setValue(sf.getValue('DEPT_NAME_LOC'));
		        			} else if (Sepoa.info.LANGUAGE == 'JA') {
		        				gridObj.cells(rId, colIdxDeptName).setValue(sf.getValue('DEPT_NAME_JP'));
		        			} else if (Sepoa.info.LANGUAGE == 'ZH') {
		        				gridObj.cells(rId, colIdxDeptName).setValue(sf.getValue('DEPT_NAME_CN'));
		        			} else {
		        				gridObj.cells(rId, colIdxDeptName).setValue(sf.getValue('DEPT_NAME_ENG'));
		        			}
	        			} else {
	        				Alert(so.message);
	        			}
	        		});
	        	} else if (cInd==colIdxPos) {
	        		if (gridObj.cells(rId, colIdxPos).getValue()=='') {
	        			return false;
	        		}
	        		dataOutput.setValue('HOUSE_CODE', formObj.getValue('HOUSE_CODE'));
	        		dataOutput.setValue('COMPANY_CODE', gridObj.cells(rId, colIdxCompany).getValue());
	        		dataOutput.setValue('POSITION_CODE', gridObj.cells(rId, colIdxPos).getValue());
	        		doServiceAjax('sepoa.svc.info.SepoaInfoUploadService', 'CONNECTION', 'searchPosition', null, function(so){
	        			if (so.status == 1){
	        				var sf = new SepoaFormater(so.result[0]);
	        				if (Sepoa.info.LANGUAGE == 'KO') {
	        					gridObj.cells(rId, colIdxPosName).setValue(sf.getValue('POSITION_NAME_LOC'));
		        			} else if (Sepoa.info.LANGUAGE == 'JA') {
		        				gridObj.cells(rId, colIdxPosName).setValue(sf.getValue('POSITION_NAME_JP'));
		        			} else if (Sepoa.info.LANGUAGE == 'ZH') {
		        				gridObj.cells(rId, colIdxPosName).setValue(sf.getValue('POSITION_NAME_CN'));
		        			} else {
		        				gridObj.cells(rId, colIdxPosName).setValue(sf.getValue('POSITION_NAME_ENG'));
		        			}
	        			} else {
	        				Alert(so.message);
	        			}
	        		});
	        	}
        	}
        	return true;
